"""Build an offline-ready teaching deck from reviewed Wiki and evidence notes."""
import html,json,hashlib,datetime,zipfile
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def load(p):return json.loads((ROOT/p).read_text())
S=load('intake/sources.json');W=load('wiki/entries.json');B=load('runs/baseline.json');R=load('runs/improved.json')
def card(title,body):return '<article class="card"><h3>'+title+'</h3><p>'+body+'</p></article>'
def cards(*items):return '<div class="cards">'+''.join(card(*x) for x in items)+'</div>'
def callout(t):return '<p class="callout">'+t+'</p>'
slides=[]
def slide(title,lead,body,refs,wiki,notes,kicker='資安產業研究入門'):
    slides.append(dict(title=title,lead=lead,html=body,sources=refs,wiki=wiki,notes=notes,kicker=kicker))
