assert len(slides)==18
(ROOT/'deck.json').write_text(json.dumps(slides,ensure_ascii=False,indent=2)+'\n')
for d in slides:
    assert set(d['sources']) <= {s['id'] for s in S}
    assert set(d['wiki']) <= {e['id'] for e in W}
    assert d['notes']

